{"implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    node_dict = {node['id']: node for node in nodes}
    children = {}
    for node in nodes:
        pid = node.get('parent')
        if pid is not None:
            children.setdefault(pid, []).append(node['id'])
    retained = set(node['id'] for node in nodes)
    required_counts = {sym: 0 for sym in required_symbols}
    for node in nodes:
        if node['symbol'] in required_counts:
            required_counts[node['symbol']] += 1
    removables = [node for node in nodes if node.get('removable', False)]
    removables.sort(key=lambda n: (-n['depth'], n['id']))
    removed_order = []
    for node in removables:
        nid = node['id']
        if nid not in retained:
            continue
        child_ids = children.get(nid, [])
        if any(cid in retained for cid in child_ids):
            continue
        sym = node['symbol']
        if sym in required_counts:
            if required_counts[sym] <= 1:
                continue
            required_counts[sym] -= 1
        retained.remove(nid)
        removed_order.append(nid)
    retained_node_ids = sorted(retained)
    return {"removed_node_ids": removed_order, "retained_node_ids": retained_node_ids}"}
